/*
 * A composed `-icon-<name>` rides the shared icon painter (utilities/icon), so a text button needs no
 * button-specific glyph CSS — the ::before already inherits the label's colour and 1em size. Icon-only
 * shape buttons carry no label, so grow the glyph to fill the square control rather than tracking a
 * (missing) label's cap height.
 */
&:is([class^="-icon-"], [class*=" -icon-"])::before {
  display: inline-block;
  inline-size: 1em;
  block-size: 1em;
  flex: none;
  margin-inline-end: var(--instui-spacing-space-xs);
  vertical-align: -0.125em;
  background: currentColor;
  -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
  mask: var(--pantoken-glyph) center / contain no-repeat;
}

&.-shape-square:is([class^="-icon-"], [class*=" -icon-"])::before,
&.-shape-circle:is([class^="-icon-"], [class*=" -icon-"])::before,
&:is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *))::before,
&:is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child)::before,
&:is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content):has(> .tip):not(
    :has(> :not(.pfx-screen-reader-content):not(.tip))
  )::before {
  inline-size: 1.25em;
  block-size: 1.25em;
  margin-inline-end: 0;
}

